<?php
require_once __DIR__.'/../includes/db_connect.php';require_once __DIR__.'/../includes/media_helpers.php';require_once __DIR__.'/../includes/club_helpers.php';
$raw=urldecode((string)($_GET['club']??''));$club=canonical_club_name($raw)?:trim($raw);if($club===''){http_response_code(404);exit;}$aliases=database_club_aliases($pdo,$club);$ph=implode(',',array_fill(0,count($aliases),'?'));
$logoStmt=$pdo->prepare("SELECT logo_url FROM club_logos WHERE club_name IN ($ph) ORDER BY club_name=? DESC LIMIT 1");$logoStmt->execute([...$aliases,$club]);$logo=article_image_url($logoStmt->fetchColumn()?:null);
$articleStmt=$pdo->prepare("SELECT DISTINCT a.title,a.slug,a.image,a.summary,a.created_at FROM articles a JOIN article_tags at ON at.article_id=a.id JOIN tags t ON t.id=at.tag_id WHERE t.name IN ($ph) AND a.status='published' ORDER BY a.created_at DESC LIMIT 12");$articleStmt->execute($aliases);$articles=$articleStmt->fetchAll();
$standingStmt=$pdo->prepare("SELECT league_name,position,played,points FROM league_standings WHERE team IN ($ph) LIMIT 1");$standingStmt->execute($aliases);$standing=$standingStmt->fetch();
$matchStmt=$pdo->prepare("SELECT home_team,away_team,match_time,match_status,slug FROM matches WHERE home_team IN ($ph) OR away_team IN ($ph) ORDER BY id DESC LIMIT 10");$matchStmt->execute([...$aliases,...$aliases]);$matches=$matchStmt->fetchAll();
?><!doctype html><html lang="ka"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<?php require __DIR__ . '/../includes/head_meta.php'; ?><title><?= htmlspecialchars($club) ?> | Sport Blog</title><link rel="stylesheet" href="/sport_blog/css/styles.css?v=20261119g"><link rel="stylesheet" href="/sport_blog/css/navbar.css?v=20261119g"><link rel="stylesheet" href="/sport_blog/css/club.css?v=20261119g"></head><body><?php require __DIR__.'/../includes/header.php'; ?><main class="club-page"><header class="club-hero"><img src="<?= htmlspecialchars($logo) ?>" alt="" width="140" height="140"><div><p>კლუბი</p><h1><?= htmlspecialchars($club) ?></h1><?php if($standing): ?><span>პოზიცია: <?= (int)$standing['position'] ?> · მატჩები: <?= (int)$standing['played'] ?> · ქულა: <?= (int)$standing['points'] ?></span><?php endif; ?></div></header><section><h2>სტატიები</h2><div class="club-articles"><?php foreach($articles as $a): ?><a href="/sport_blog/news/<?= htmlspecialchars($a['slug']) ?>"><img src="<?= htmlspecialchars(article_image_url($a['image'])) ?>" width="320" height="180" alt=""><strong><?= htmlspecialchars($a['title']) ?></strong></a><?php endforeach; ?><?php if(!$articles): ?><p>სტატიები ჯერ არ არის.</p><?php endif; ?></div></section><section><h2>მატჩები</h2><div class="club-matches"><?php foreach($matches as $m): ?><a href="/sport_blog/matches/<?= htmlspecialchars($m['slug']) ?>"><strong><?= htmlspecialchars($m['home_team'].' — '.$m['away_team']) ?></strong><span><?= htmlspecialchars($m['match_status']?:$m['match_time']) ?></span></a><?php endforeach; ?><?php if(!$matches): ?><p>მატჩები ჯერ არ არის.</p><?php endif; ?></div></section></main><?php require __DIR__.'/../includes/footer.php'; ?></body></html>
